using System.Collections.ObjectModel;
using System.Windows.Input;
using WAID.Application.Services;
using WAID.Application.Abstractions;

namespace WAID.Desktop.ViewModels;
public sealed class RepairOrchestrationViewModel:ViewModelBase
{
 private readonly RepairOrchestrator _orchestrator;private readonly IRepairOrchestrationRepository _repository;private readonly IRecoveryArtifactRepository _artifacts;private readonly IRecoveryRetentionService _retention;private readonly IRecoveryWorkflow _recoveryWorkflow;private CancellationTokenSource? _cancellation;private RepairOrchestrationRecord? _current;private string? _selectedRepairId;private string _status="Select a repair to assess and simulate. No changes occur during simulation.";private bool _approved;private bool _riskAcknowledged;private bool _rollbackConfirmed;private bool _showTechnical;private RecoveryArtifactRecord? _selectedArtifact;private double _progress;
 public RepairOrchestrationViewModel(RepairRegistry registry,RepairOrchestrator orchestrator,IRepairOrchestrationRepository repository,IRecoveryArtifactRepository artifacts,IRecoveryRetentionService retention,IRecoveryWorkflow recoveryWorkflow){_orchestrator=orchestrator;_repository=repository;_artifacts=artifacts;_retention=retention;_recoveryWorkflow=recoveryWorkflow;Repairs=registry.All.OrderBy(x=>x.DisplayName).Select(x=>new RepairLifecycleOption(x.Id,x.DisplayName,x.Description,x.Policy.SafetyLevel)).ToArray();_selectedRepairId=Repairs.FirstOrDefault()?.Id;SimulateCommand=new AsyncCommand(SimulateAsync);ExecuteCommand=new AsyncCommand(ExecuteAsync);CancelCommand=new AsyncCommand(CancelAsync);RefreshCommand=new AsyncCommand(LoadAsync);RecoverCommand=new AsyncCommand(RecoverAsync);CleanupArtifactsCommand=new AsyncCommand(CleanupArtifactsAsync);RollbackArtifactCommand=new AsyncCommand(RollbackArtifactAsync);}
 public IReadOnlyList<RepairLifecycleOption>Repairs{get;}public ObservableCollection<RepairOrchestrationStep>Steps{get;}=[];public ObservableCollection<RepairOrchestrationRecord>History{get;}=[];public ObservableCollection<RecoveryArtifactRecord>RecoveryArtifacts{get;}=[];public ICommand SimulateCommand{get;}public ICommand ExecuteCommand{get;}public ICommand CancelCommand{get;}public ICommand RefreshCommand{get;}public ICommand RecoverCommand{get;}public ICommand CleanupArtifactsCommand{get;}public ICommand RollbackArtifactCommand{get;}
 public bool RollbackConfirmed{get=>_rollbackConfirmed;set=>Set(ref _rollbackConfirmed,value);}public RecoveryArtifactRecord? SelectedArtifact{get=>_selectedArtifact;set=>Set(ref _selectedArtifact,value);}public string? SelectedRepairId{get=>_selectedRepairId;set{if(Current?.Stage==RepairOrchestrationStage.AwaitingApproval&&value!=Current.RepairId){Status="Finish or cancel the restored repair plan before selecting another repair.";return;}Set(ref _selectedRepairId,value);}}public bool Approved{get=>_approved;set=>Set(ref _approved,value);}public bool RiskAcknowledged{get=>_riskAcknowledged;set=>Set(ref _riskAcknowledged,value);}public bool ShowTechnical{get=>_showTechnical;set{if(Set(ref _showTechnical,value))Notify(nameof(DisplayedSummary));}}public string Status{get=>_status;private set=>Set(ref _status,value);}public double Progress{get=>_progress;private set=>Set(ref _progress,value);}public RepairOrchestrationRecord? Current{get=>_current;private set{if(Set(ref _current,value))NotifySummary();}}
 public string CurrentScreen=>Current?.UiState?.Screen.ToString()??"Plan review";public string CurrentAction=>Current?.UiState?.CurrentAction??Status;public string DisplayedSummary=>Current?.UiState is{}state?(ShowTechnical?state.TechnicalSummary:state.PlainSummary):"No active repair workflow."; public IReadOnlyList<RepairSafetyFactor> SafetyFactors=>Current?.Simulation?.SafetyAssessment?.Factors??[];public string SafetyScore=>Current?.Simulation?.SafetyAssessment is{}s?$"Safety score: {s.Score}/100 ({s.ScoringVersion})":"Safety score: not calculated";public string ApprovalRequirement=>Current?.Simulation?.SafetyAssessment is{}s?$"Confirmation: {s.RequiredApproval}":"Confirmation: not calculated";public string PolicyDecision=>Current?.Simulation?.SafetyAssessment is{}s?$"Policy {s.PolicyVersion}: {s.PolicyResult}. {s.Explanation}":"Policy decision: not calculated";public string SafetyExceptions=>Current?.Simulation?.SafetyAssessment is{}s?string.Join(" ",s.PolicyRequirements.Concat(s.Exceptions)):"No policy requirements or scoring exceptions.";
 public IReadOnlyList<RepairPredictedEffect> Effects=>Current?.Simulation?.Effects??[];public string SimulationMetadata=>Current?.Simulation is{}s?$"{s.SimulationVersion}; created {s.SimulatedAtUtc:u}; valid until {s.ValidUntilUtc:u}; fingerprint {s.Fingerprint[..Math.Min(12,s.Fingerprint.Length)]}":"Not simulated";public string Duration=>Current?.Simulation?.EstimatedDuration is{}duration?$"Estimated duration: {duration.TotalMinutes:0} minute(s)":"Duration: unknown";public string PredictedRestart=>Current?.Simulation?.PredictedRestartRequired switch{true=>"Restart predicted: yes",false=>"Restart predicted: no",_=>"Restart prediction: unknown"};public string RollbackReadiness=>Current?.Simulation is{}s?s.SupportsRollback&&s.RequiresBackup?"Rollback readiness: backup required and supported":s.SupportsRollback?"Rollback readiness: supported":"Rollback readiness: not supported":"Rollback readiness: unknown";public string SimulationWarnings=>Current?.Simulation is{}s?string.Join(" ",s.Warnings.Concat(s.Assumptions)):"No simulation warnings available";
 public string Risk=>Current?.Simulation?.Risk.ToString()??"Not assessed";public string Safeguards=>Current?.Simulation is{}s?$"Administrator: {s.RequiresAdministrator}; restore point: {s.RequiresRestorePoint}; backup: {s.RequiresBackup}; rollback: {s.SupportsRollback}":"Not assessed";public string Restart=>Current is null?"Unknown":Current.RestartRequired?"Restart required":"No restart reported";public string Validation=>Current?.Validation?.Summary??"Not yet validated";public string Backup=>Current?.BackupLocation??"No backup checkpoint recorded";public string Outcome=>Current?.Outcome??"No active lifecycle";
 public async Task LoadAsync(){try{History.Clear();foreach(var x in await _repository.GetRecentAsync(50,CancellationToken.None))History.Add(x);RecoveryArtifacts.Clear();foreach(var artifact in await _artifacts.GetRecentAsync(100,CancellationToken.None))RecoveryArtifacts.Add(artifact);var resumable=(await _repository.GetNonTerminalAsync(CancellationToken.None)).Where(x=>x.Stage==RepairOrchestrationStage.AwaitingApproval&&x.Simulation is not null).OrderByDescending(x=>x.UpdatedAtUtc).FirstOrDefault();if(resumable is not null){Current=resumable;_selectedRepairId=resumable.RepairId;Notify(nameof(SelectedRepairId));RefreshSteps();Status=resumable.UiState?.CurrentAction??resumable.Outcome;}else Status=$"Loaded {History.Count} repair lifecycle record(s) and {RecoveryArtifacts.Count} recovery artifact(s).";}catch(Exception ex){Status=$"Repair lifecycle history unavailable ({ex.GetType().Name}).";}}
 private async Task SimulateAsync(){if(string.IsNullOrWhiteSpace(SelectedRepairId)){Status="Select a repair first.";return;}_cancellation?.Dispose();_cancellation=new();try{Approved=false;RiskAcknowledged=false;Progress=0;var progress=new Progress<RepairProgress>(UpdateProgress);Current=await _orchestrator.AssessAndSimulateAsync(new(SelectedRepairId,null,new HashSet<string>(StringComparer.OrdinalIgnoreCase),new HashSet<string>(StringComparer.OrdinalIgnoreCase)),progress,_cancellation.Token);RefreshSteps();Status=Current.Outcome;}catch(OperationCanceledException){Status="Assessment cancelled before execution.";}catch(RepairOrchestrationException ex){Status=$"{ex.Message} {ex.RecoveryAction}";}catch(Exception ex){Status=$"Assessment failed safely ({ex.GetType().Name}). Review Logs & Audit.";}}
 private async Task ExecuteAsync(){if(Current is null){Status="Assess and simulate a repair before execution.";return;}_cancellation?.Dispose();_cancellation=new();try{var progress=new Progress<RepairProgress>(UpdateProgress);Current=await _orchestrator.ExecuteAsync(Current.Id,Approved,RiskAcknowledged,progress,_cancellation.Token);RefreshSteps();Status=Current.Outcome;await LoadAsync();}catch(OperationCanceledException){Status="Cancellation requested. Review lifecycle and repair history for rollback status.";}catch(RepairOrchestrationException ex){Status=$"{ex.Message} {ex.RecoveryAction}";}catch(Exception ex){Status=$"Repair stopped safely ({ex.GetType().Name}). Review lifecycle recovery and Logs & Audit.";}}
 private async Task CancelAsync(){if(!ExecuteCommand.CanExecute(null)){_cancellation?.Cancel();Status="Cancellation requested. Wait for the persisted repair outcome.";return;}if(Current?.Stage==RepairOrchestrationStage.AwaitingApproval){try{Current=await _orchestrator.CancelAsync(Current.Id,CancellationToken.None);RefreshSteps();Status=Current.Outcome;await LoadAsync();}catch(Exception ex){Status=$"Cancellation failed safely ({ex.GetType().Name}). Review Logs & Audit.";}return;}_cancellation?.Cancel();}
 private async Task RecoverAsync(){try{var recovered=await _orchestrator.RecoverInterruptedAsync(CancellationToken.None);Status=recovered.Count==0?"No interrupted repair lifecycle requires recovery.":$"Recovered {recovered.Count} interrupted lifecycle(s). Execution was not repeated.";await LoadAsync();}catch(Exception ex){Status=$"Recovery check failed ({ex.GetType().Name}). Do not rerun a repair until history is reviewed.";}}
 private async Task CleanupArtifactsAsync(){try{var result=await _retention.DeleteExpiredAsync(CancellationToken.None);Status=$"Deleted {result.Deleted} expired artifact(s); {result.Failed} failed.";await LoadAsync();}catch(Exception ex){Status=$"Recovery retention failed safely ({ex.GetType().Name}).";}}
 private async Task RollbackArtifactAsync(){if(SelectedArtifact is null){Status="Select a recovery artifact first.";return;}try{var result=await _recoveryWorkflow.RollbackAsync(SelectedArtifact.TransactionId,RollbackConfirmed,CancellationToken.None);Status=result.Detail;RollbackConfirmed=false;await LoadAsync();}catch(OperationCanceledException){Status="Rollback cancelled.";}catch(Exception ex){Status=$"Rollback failed safely ({ex.GetType().Name}). Review Logs & Audit.";}}
 private void UpdateProgress(RepairProgress p){Progress=p.Percentage;Status=$"{p.Stage}: {p.Detail}";}
 private void RefreshSteps(){Steps.Clear();if(Current is not null)foreach(var x in Current.Steps)Steps.Add(x);NotifySummary();}
 private void NotifySummary(){Notify(nameof(CurrentScreen));Notify(nameof(CurrentAction));Notify(nameof(DisplayedSummary));Notify(nameof(SafetyFactors));Notify(nameof(SafetyScore));Notify(nameof(ApprovalRequirement));Notify(nameof(PolicyDecision));Notify(nameof(SafetyExceptions));Notify(nameof(Effects));Notify(nameof(SimulationMetadata));Notify(nameof(Duration));Notify(nameof(PredictedRestart));Notify(nameof(RollbackReadiness));Notify(nameof(SimulationWarnings));Notify(nameof(Risk));Notify(nameof(Safeguards));Notify(nameof(Restart));Notify(nameof(Validation));Notify(nameof(Backup));Notify(nameof(Outcome));}
}
public sealed record RepairLifecycleOption(string Id,string DisplayName,string Description,WAID.Domain.Repairs.SafetyLevel Risk);
